import urllib.request
import urllib.parse
import ssl
import re
import time

keyword = 'AI 医疗 最新进展 2025'
encoded = urllib.parse.quote(keyword)

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

def fetch(url, timeout=8):
    try:
        req = urllib.request.Request(url, headers={
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        })
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
            html = r.read().decode('utf-8', errors='ignore')
            # 简单提取标题
            titles = re.findall(r'<title>(.*?)</title>', html, re.I)
            snippet = re.findall(r'<meta[^>]+content="([^"]{50,200})"', html)
            return {'url': url[:60], 'title': titles[0][:60] if titles else 'N/A', 'snippet': snippet[0][:80] if snippet else 'N/A'}
    except Exception as e:
        return {'url': url[:60], 'error': str(e)[:50]}

# 测试几个引擎
engines = {
    '百度': f'https://www.baidu.com/s?wd={encoded}',
    'Bing国际': f'https://cn.bing.com/search?q={encoded}&ensearch=1',
    'DuckDuckGo': f'https://duckduckgo.com/html/?q={encoded}',
    'Brave': f'https://search.brave.com/search?q={encoded}',
    'Google': f'https://www.google.com/search?q={encoded}',
}

for name, url in engines.items():
    print(f'\n=== {name} ===')
    r = fetch(url)
    if 'error' in r:
        print(f'❌ {r["error"]}')
    else:
        print(f'✅ {r["title"]}')
    time.sleep(0.5)
